# Run 3, cell 1. Write edit v4 (neuron 1488 of layer 23, from run 2: design_v4.pt) into the run-3 store.
# Then thinking-mode generation requests (both arms) on the fresh sets tA and mA.
import json
d4 = torch.load("design_v4.pt", weights_only=False); u = torch.load("design_A.pt", weights_only=False)["u"]
J = 1488
gn, un, dn = (f"model.language_model.layers.23.mlp.{t}_proj.weight" for t in ("gate", "up", "down"))
Wg, Wu, Wd = load_original(gn), load_original(un), load_original(dn)
Wg[J] = d4["gate"].to(Wg.dtype); Wu[J] = d4["up"].to(Wu.dtype); Wd[:, J] = (d4["K"] * u).to(Wd.dtype)
for name, W in ((gn, Wg), (un, Wu), (dn, Wd)): save_edit(name, W)
print("v4 loaded; changed weights", sum(int((load(n) != load_original(n)).sum()) for n in (gn, un, dn)))
V2 = "@ROOT@/v2/"
def args_map(a):
    while isinstance(a, str):
        try: a = json.loads(a)
        except Exception: return {"value": a}
    return a if isinstance(a, dict) else {"value": a}
def fix_api(ms):
    return [{**m, "tool_calls": [{**c, "function": {**c["function"], "arguments": json.dumps(args_map(c["function"]["arguments"]))}} for c in m["tool_calls"]]} if m.get("tool_calls") else m for m in ms]
for s in ("tA", "mA"):
    R = [json.loads(l) for l in open(V2 + f"cells/run3/{s}.jsonl")]
    json.dump({"type": "generate", "model": "both", "enable_thinking": True, "max_tokens": 8192, "temperature": 1.0,
               "top_p": 0.95, "top_k": 20, "presence_penalty": 1.5, "seed": 0,
               "items": [{"messages": fix_api(r["messages"]), "tools": r["tools"]} for r in R]}, open(f"req-gen-{s}-think.json", "w"))
    print(s, len(R))

# Run 3, cell 2. Thinking-mode probes on tA and mA (base reasoning from passes 1, 2; original arm).
# Positions: the decision position (after "</think>\n\n"); and, when the base wrote text and then called,
# the position before that late "<tool_call>". Reads: layer-23 MLP input, residual before layer 16.
import json
V2 = "@ROOT@/v2/"
P = {p["pass"]: p["result"].get("file") for p in map(json.loads, open("passes.jsonl")) if p["status"] == "done"}
TC = tok.convert_tokens_to_ids("<tool_call>")
def args_map(a):
    while isinstance(a, str):
        try: a = json.loads(a)
        except Exception: return {"value": a}
    return a if isinstance(a, dict) else {"value": a}
def fix(ms):
    return [{**m, "tool_calls": [{**c, "function": {**c["function"], "arguments": args_map(c["function"]["arguments"])}} for c in m["tool_calls"]]} if m.get("tool_calls") else m for m in ms]
meta = {}
for p, s in ((1, "tA"), (2, "mA")):
    R = [json.loads(l) for l in open(V2 + f"cells/run3/{s}.jsonl")]; out = json.load(open(P[p]))["original"]
    texts, pos, info = [], [], []
    for r, o in zip(R, out):
        smp = o["samples"][0]
        t = tok.apply_chat_template(fix(r["messages"]), tools=r["tools"], add_generation_prompt=True, tokenize=False, enable_thinking=True)
        t += (smp["reasoning"] or "").strip("\n") + "\n</think>\n\n"
        n = len(tok(t, add_special_tokens=False)["input_ids"]); ps = [n - 1]; late = False
        content = (smp["content"] or "").strip()
        if smp["tool_calls"] and content:
            t2 = t + content + "\n\n"; ps.append(len(tok(t2, add_special_tokens=False)["input_ids"]) - 1); t = t2; late = True
        texts.append(t); pos.append(ps)
        info.append({"id": r["id"], "label": r["label"], "group": r["detail"].get("group", r["label"]),
                     "called": bool(smp["tool_calls"]), "late": late})
    json.dump({"type": "probe", "model": "original", "texts": texts, "positions": pos, "mlp_in": [23], "hidden": [16], "token_ids": [TC]},
              open(f"req-probe-{s}-think.json", "w"))
    meta[s] = info; print(s, len(texts), "late-call rows", sum(i["late"] for i in info), "max chars", max(map(len, texts)))
json.dump(meta, open("probe-meta-think.json", "w"))

# Run 3, cell 3. Thinking mode on fresh sets tA (single-turn) and mA (multi-turn).
# (1) Behavior, passes 1 and 2 (base vs v4). (2) Reads at the thinking decision position (passes 3, 4): CV LDA
# (8 folds: tA by question, mA by conversation) against the model's p_call. (3) The v4 gate in thinking mode.
import json
V2 = "@ROOT@/v2/"
P = {p["pass"]: p["result"] for p in map(json.loads, open("passes.jsonl")) if p["status"] == "done"}
meta = json.load(open("probe-meta-think.json"))
def auroc(s, y):
    s = torch.as_tensor(s, dtype=torch.float64); y = torch.as_tensor(y).bool()
    order = torch.argsort(s); r = torch.empty_like(s); r[order] = torch.arange(1, len(s) + 1, dtype=torch.float64)
    n1, n0 = int(y.sum()), int((~y).sum()); return float((r[y].sum() - n1 * (n1 + 1) / 2) / (n1 * n0))
def lda(X1, X0, lam):
    S = torch.cov(torch.cat([X1 - X1.mean(0), X0 - X0.mean(0)]).T)
    S = S + lam * S.diagonal().mean() * torch.eye(S.shape[0], dtype=S.dtype)
    return torch.linalg.solve(S, X1.mean(0) - X0.mean(0))
for p, s in ((1, "tA"), (2, "mA")):
    R = [json.loads(l) for l in open(V2 + f"cells/run3/{s}.jsonl")]; out = json.load(open(P[p]["file"]))
    for arm in ("original", "edited"):
        st = {}; ok = 0
        for r, o in zip(R, out[arm]):
            c = bool(o["samples"][0]["tool_calls"]); g = r["detail"]["group"]; a = st.setdefault(g, [0, 0]); a[0] += 1; a[1] += c
            ok += c == (r["label"] == "call")
        print(f"{s} think {arm:8s} decision acc {ok / len(R):.3f} | " + ", ".join(f"{k} call {v[1] / v[0]:.2f}" for k, v in st.items()))
d4 = torch.load("design_v4.pt", weights_only=False); silu = torch.nn.functional.silu
D = {}
for p, s in ((3, "tA"), (4, "mA")):
    z = np.load(P[p]["file"]); info = meta[s]; first = {}
    for k, (i, _) in enumerate(z["rows"]): first.setdefault(int(i), k)
    idx = [first[i] for i in range(len(info))]
    X = {k: torch.tensor(z[k]).double()[idx] for k in ("mlp_in_23", "hidden_16")}; lp = torch.tensor(z["logp"][:, 0]).double()[idx]
    y = torch.tensor([m["label"] == "call" for m in info])
    fold = torch.tensor([(i % 96) % 8 if i < 192 else i % 8 for i in range(len(info))]) if s == "tA" else \
           torch.tensor([int(m["id"].split("-")[1]) % 8 for m in info])
    print(f"{s} think: model p_call AUROC {auroc(lp, y):.3f}")
    for key in ("mlp_in_23", "hidden_16"):
        for lam in (1.0, 3.0, 10.0, 30.0):
            sc = torch.zeros(len(y), dtype=torch.float64)
            for f in range(8):
                te = fold == f; tr = ~te; sc[te] = X[key][te] @ lda(X[key][tr & y], X[key][tr & ~y], lam)
            print(f"   CV read {key:10s} lam {lam:5.1f} AUROC {auroc(sc, y):.3f}")
    pre = X["mlp_in_23"] @ d4["gate"].double()
    print(f"   v4 gate in thinking mode: share open {float((pre > 0).double().mean()):.3f}, mean |K h| {float((d4['K'] * silu(pre) * (X['mlp_in_23'] @ d4['up'].double())).abs().mean()):.3f}")
    g = np.array([m["group"] for m in info])
    for grp in sorted(set(g)): print(f"   mean p_call {grp}: {float(lp.exp()[torch.tensor(g == grp)].mean()):.3f}")
    D[s] = {"X": X["mlp_in_23"], "y": y, "lp": lp, "fold": fold, "group": g.tolist()}
torch.save(D, "think_A.pt")

