def dec_and_bg(path):
    z = np.load(path); X = torch.tensor(z["mlp_in_23"]).double(); first = {}
    for k, (i, _) in enumerate(z["rows"]): first.setdefault(int(i), k)
    d = torch.zeros(len(X), dtype=torch.bool); d[list(first.values())] = True
    return X[d], X[~d]
groups = {}
for p in (3, 4):
